function normalizeDriveId(raw, label) {
  const s = String(raw || '').trim();
  if (!s) return '';
  if (s.includes('googleusercontent.com')) {
    throw new Error(label + ' looks like a Google OAuth Client ID  -  use the folder/file ID from the Drive URL');
  }
  const folderMatch = s.match(/\/folders\/([a-zA-Z0-9_-]+)/);
  if (folderMatch) return folderMatch[1];
  const fileMatch = s.match(/\/file\/d\/([a-zA-Z0-9_-]+)/);
  if (fileMatch) return fileMatch[1];
  if (s.includes('/')) {
    throw new Error(label + ' is invalid  -  paste only the ID from the Drive URL (no slashes). Example: 1H3huWIa3RiWu4md95eBPs-QecKr1vhJN');
  }
  return s;
}

const baseUrl = ($env.JMTS_API_BASE_URL || 'http://host.docker.internal:3000').replace(/\/+$/, '');
const driveFolderId = normalizeDriveId($env.GOOGLE_DRIVE_FOLDER_ID, 'GOOGLE_DRIVE_FOLDER_ID');
const driveFileId = normalizeDriveId($env.GOOGLE_DRIVE_FILE_ID, 'GOOGLE_DRIVE_FILE_ID');
const openAiModel = ($env.OPENAI_MODEL || 'gpt-4o-mini').trim();

if (!driveFolderId && !driveFileId) {
  throw new Error('Set GOOGLE_DRIVE_FOLDER_ID (recommended) or GOOGLE_DRIVE_FILE_ID in .env');
}

return [{ json: { baseUrl, driveFolderId, driveFileId, useFolder: !!driveFolderId, openAiModel } }];

const subfolderIds = [];
for (const item of $('2b-1 List root').all()) {
  if (item.json?.mimeType === 'application/vnd.google-apps.folder' && item.json?.id) {
    subfolderIds.push({ id: item.json.id, name: item.json.name });
  }
}
return [{ json: { subfolderIds } }];

const subfolderIds = [];
for (const item of $('2b-3 List subfolders L1').all()) {
  if (item.json?.mimeType === 'application/vnd.google-apps.folder' && item.json?.id) {
    subfolderIds.push({ id: item.json.id, name: item.json.name });
  }
}
return [{ json: { subfolderIds } }];

/**
 * n8n node "2b-6 Merge all files"  -  dedupe files from all Drive list nodes.
 */
function fileItems(nodeName) {
  try {
    return $(nodeName).all()
      .filter((i) => i.json?.id && i.json.mimeType !== 'application/vnd.google-apps.folder')
      .map((i) => i.json);
  } catch {
    return [];
  }
}

const seen = new Set();
const out = [];
const sources = [
  '2b-1 List root',
  '2b-3 List subfolders L1',
  '2b-5 List subfolders L2',
  '2b-5 List subfolders L3',
];

for (const name of sources) {
  for (const f of fileItems(name)) {
    if (!f.id || seen.has(f.id)) continue;
    seen.add(f.id);
    out.push({ json: { id: f.id, name: String(f.name || f.id), mimeType: String(f.mimeType || '') } });
  }
}

if (out.length === 0) {
  throw new Error('No files found in Drive folder tree. Check GOOGLE_DRIVE_FOLDER_ID and Google OAuth access.');
}

return out;

/**
 * n8n node "2f. Prepare extract payload"  -  skip bad downloads, never fail the whole batch.
 */
const items = $input.all();
const results = [];
const skipped = [];

for (let index = 0; index < items.length; index++) {
  const item = items[index];
  const json = item.json || {};
  let filename = String(json.name || json.filename || json.id || 'unknown');
  let mimeType = String(json.mimeType || '');
  const binary = item.binary || {};
  const binaryKey = Object.keys(binary)[0];

  if (!binaryKey) {
    skipped.push({ filename, reason: 'no_binary_from_drive' });
    continue;
  }

  let buffer;
  try {
    buffer = await this.helpers.getBinaryDataBuffer(index, binaryKey);
  } catch (err) {
    skipped.push({ filename, reason: err?.message || 'binary_read_failed' });
    continue;
  }

  if (!buffer?.length) {
    skipped.push({ filename, reason: 'empty_download' });
    continue;
  }

  if (mimeType.startsWith('application/vnd.google-apps.')) {
    if (mimeType.includes('spreadsheet')) mimeType = 'text/csv';
    else if (mimeType.includes('presentation')) mimeType = 'text/plain';
    else mimeType = 'application/vnd.openxmlformats-officedocument.wordprocessingml.document';
  }

  const isPdf = mimeType === 'application/pdf' || filename.toLowerCase().endsWith('.pdf');
  if (isPdf && !buffer.subarray(0, 5).toString('latin1').startsWith('%PDF')) {
    skipped.push({ filename, reason: 'invalid_pdf_bytes' });
    continue;
  }

  const isServiceImage =
    ['image/png', 'image/jpeg', 'image/webp', 'image/gif'].includes(mimeType) ||
    /\.(png|jpe?g|webp|gif)$/i.test(filename);

  results.push({
    json: {
      filename,
      mimeType,
      contentBase64: buffer.toString('base64'),
      isServiceImage,
    },
  });
}

if (results.length === 0) {
  throw new Error('No downloadable Drive files. Skipped: ' + JSON.stringify(skipped));
}

return results;

/**
 * n8n node "2h. Aggregate extracted content"
 * Reads directly from extract/upload nodes (merge input is unreliable with large binaries).
 */
function collectItems() {
  const out = [];
  for (const name of ['2g-img. JMT-S Upload image', '2g. JMT-S Extract text']) {
    try {
      out.push(...$(name).all());
    } catch {
      // node did not run
    }
  }
  if (out.length > 0) return out;
  return $input.all();
}

const items = collectItems();
const parts = [];
const skipped = [];
const uploadedImages = [];
const extractErrors = [];

function isHttpError(json) {
  if (!json || typeof json !== 'object') return false;
  if (json.status === 'success' || json.status === 'no_text') return false;
  if (Array.isArray(json.results) && json.results.length > 0) return false;
  return Boolean(json.error || json.message);
}

function ingestExtractPayload(json) {
  if (!Array.isArray(json.results)) return;
  for (const result of json.results) {
    if (!result || typeof result !== 'object') continue;
    if (result.skipped || !String(result.text || '').trim()) {
      skipped.push({
        filename: result.filename || 'unknown',
        reason: result.reason || result.mode || 'empty',
        mode: result.mode || null,
      });
      continue;
    }
    parts.push('=== ' + (result.filename || 'unknown') + ' ===\n' + String(result.text).trim());
  }
}

for (const item of items) {
  const json = item.json || {};

  if (json.url && json.filename && json.status === 'success') {
    uploadedImages.push({ filename: json.filename, url: json.url });
    continue;
  }

  if (isHttpError(json)) {
    extractErrors.push({
      filename: json.filename || 'unknown',
      reason:
        (json.error && json.error.message) ||
        json.message ||
        (typeof json.error === 'string' ? json.error : 'extract_http_error'),
    });
    continue;
  }

  ingestExtractPayload(json);
}

let driveText = parts.join('\n\n');

if (!driveText.trim() && uploadedImages.length > 0) {
  driveText = uploadedImages
    .map((img) => '=== ' + img.filename + ' ===\n[Image uploaded: ' + img.url + ']')
    .join('\n\n');
}

if (!driveText.trim() && uploadedImages.length === 0) {
  const summary = {
    itemCount: items.length,
    skippedCount: skipped.length,
    errorCount: extractErrors.length,
    skipped: skipped.slice(0, 20),
    extractErrors: extractErrors.slice(0, 20),
  };
  const skippedNames = skipped.map((s) => s.filename).filter(Boolean).slice(0, 5);
  return [{
    json: {
      driveText: '',
      fileCount: 0,
      uploadedImages,
      skipped,
      extractErrors,
      driveChars: 0,
      sourceItemCount: items.length,
      noUsableContent: true,
      extractionNote:
        'No usable Drive content after extraction. Every file was skipped or failed. ' +
        'Add a Word/Google Doc export alongside scanned PDFs, or ensure GEMINI_API_KEY is set and restart Next.js.',
      extractionSummary: summary,
      skippedFilenames: skippedNames,
    },
  }];
}

return [{
  json: {
    driveText,
    fileCount: parts.length,
    totalFilesProcessed: items.length,
    uploadedImages,
    skipped,
    extractErrors,
    driveChars: driveText.length,
    sourceItemCount: items.length,
    partialExtraction: skipped.length > 0,
  },
}];

/**
 * n8n node "3. Prepare OpenAI"  -  build chat/completions payload (n8n calls OpenAI directly).
 */
const snapshot = $('1. JMT-S Snapshot').first().json;
const agg = $('2h. Aggregate extracted content').first().json;
const driveText = agg.driveText || '';
const uploadedImages = agg.uploadedImages || [];

function trimSnapshot(raw) {
  const clip = (v, max) => {
    const s = String(v ?? '');
    return s.length > max ? s.slice(0, max) + '…' : s;
  };
  return {
    fetchedAt: raw.fetchedAt,
    home: raw.home
      ? {
          id: raw.home.id,
          heroH1: raw.home.heroH1,
          heroLead: clip(raw.home.heroLead, 400),
          whyBullets: raw.home.whyBullets,
        }
      : null,
    about: raw.about
      ? {
          id: raw.about.id,
          missionLead: clip(raw.about.missionLead, 400),
          ctaTitle: raw.about.ctaTitle,
        }
      : null,
    company: raw.company
      ? {
          id: raw.company.id,
          name: raw.company.name,
          emails: raw.company.emails,
          phones: raw.company.phones,
        }
      : null,
    services: (raw.services || []).map((s) => ({
      id: s.id,
      title: s.title,
      slug: s.slug,
      shortDesc: clip(s.shortDesc, 240),
      sector: s.sector,
      detailedDesc: clip(s.detailedDesc, 600),
      imageUrl: s.imageUrl,
      isActive: s.isActive,
    })),
    announcements: (raw.announcements || []).map((a) => ({
      id: a.id,
      title: a.title,
      audience: a.audience,
      content: clip(a.content, 400),
      isActive: a.isActive,
    })),
  };
}

const systemPrompt = [
  'You are the JMT-S CMS diff engine. Synchronize the FULL public website CMS from Google Drive source material.',
  'Resources: home (hero, pillars, catalog, process steps), about (mission, bullets, CTA), company (contact, social), services, announcements.',
  'Output ONLY valid JSON: { instructionSummary: string, updates: array }. No markdown fences.',
  'Each update MUST use apply shape: { resource: "home"|"about"|"company", patch: { heroH1?, heroLead?, ... } with CMS keys directly in patch (never nest under a "fields" key). Service: { resource: "service", id: "uuid-from-snapshot", patch: { detailedDesc?, shortDesc?, ... } } OR { resource: "service", action: "create", data: { title, shortDesc, detailedDesc, sector, imageUrl? } }. NEVER put CMS fields at top level without resource+patch wrappers.',
  'Jacob dumps ALL company documents in one Drive folder (PDF, Word, Google Docs, slides, images) with NO required structure  -  infer home, about, company, services, announcements from the combined text of every file. Emit updates for EVERY section that differs or is missing on site but present in Drive.',
  'Partial patches only. Use service/announcement ids from snapshot  -  never invent UUIDs.',
  'List fields (whyBullets, approachBullets, etc.): 3-8 items, each 8-180 chars.',
  'Service shortDesc: one punchy sentence, max 240 chars, catalog card style.',
  'Service detailedDesc: HTML string with intro <p>, then <h3>Ce que nous vous proposons:</h3>, then <ul><li>...</li></ul> (3-6 bullets).',
  'Service sector: exactly education, enterprise, or both (lowercase).',
  'Service imageUrl: when driveUploadedImages contains a file whose name matches a service title/slug, set imageUrl to that exact url on create or patch. If no matching Drive image exists, omit imageUrl  -  JMT-S will auto-generate a professional service image on publish.',
  'Prefer patch existing services by id; use action:create only for new services. Prefer isActive:false over delete.',
  'If snapshot and Drive already match: updates:[].',
].join(' ');

const userContent = JSON.stringify({
  instruction:
    'Produce updates array for POST /api/agent/v1/content/apply covering home, about, company, services, announcements as needed.',
  snapshot: trimSnapshot(snapshot),
  driveSourceDocuments: driveText.slice(0, 120000),
  driveUploadedImages: uploadedImages,
  driveTextFileCount: agg.fileCount,
  skippedDriveFiles: agg.skipped || [],
});

return [
  {
    json: {
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userContent },
      ],
      driveChars: driveText.length,
      driveFileCount: agg.fileCount,
      uploadedImageCount: uploadedImages.length,
      skippedCount: (agg.skipped || []).length,
      snapshotAt: snapshot.fetchedAt,
    },
  },
];

/**
 * n8n node "5. Parse AI diff"  -  normalize OpenAI flat output into apply payload shape.
 * Keep in sync with apps/web/src/lib/validation/sanitize-agent-apply.ts coerceFlatUpdate.
 */
const raw = $('4. OpenAI diff').first().json;
const snapshot = $('1. JMT-S Snapshot').first().json;
const content = raw.choices?.[0]?.message?.content;
if (!content) throw new Error('OpenAI returned empty content');

let parsed;
try {
  parsed = JSON.parse(content);
} catch {
  throw new Error('OpenAI output is not valid JSON: ' + content.slice(0, 200));
}

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-9a-f][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const isUuid = (v) => typeof v === 'string' && UUID_RE.test(v);
const normSector = (v) => {
  const s = String(v || '').trim().toLowerCase();
  if (s.includes('edu') || s.includes('enseign')) return 'education';
  if (s.includes('enter') || s.includes('entreprise')) return 'enterprise';
  if (s === 'both') return 'both';
  return s;
};

const HOME_KEYS = [
  'heroH1', 'heroLead', 'whyBullets', 'pillarsEducationTitle', 'pillarsEducationDesc',
  'pillarsEnterpriseTitle', 'pillarsEnterpriseDesc', 'catalogKicker', 'catalogTitle', 'catalogDesc',
  'processStep1Title', 'processStep1Body', 'processStep2Title', 'processStep2Body',
  'processStep3Title', 'processStep3Body',
];
const ABOUT_KEYS = [
  'missionLead', 'missionBody', 'approachBullets', 'whyTitle', 'whySubtitle',
  'whyEducationTitle', 'whyEducationBullets', 'whyEnterpriseTitle', 'whyEnterpriseBullets',
  'challengesTitle', 'challengesBullets', 'ctaTitle', 'ctaBody',
];
const COMPANY_KEYS = ['name', 'taglinePro', 'taglineEducation', 'emails', 'phones', 'addresses', 'socialLinks'];
const SERVICE_KEYS = ['title', 'slug', 'shortDesc', 'detailedDesc', 'iconName', 'imageUrl', 'sector', 'displayOrder', 'isActive'];
const ANN_KEYS = ['title', 'content', 'audience', 'isActive'];

const pick = (src, keys) => {
  const out = {};
  for (const k of keys) {
    if (Object.prototype.hasOwnProperty.call(src, k) && src[k] !== undefined && src[k] !== null) {
      out[k] = src[k];
    }
  }
  return out;
};

const normResource = (v) => {
  const s = String(v || '').trim().toLowerCase();
  if (s === 'services' || s === 'service') return 'service';
  if (s === 'announcements' || s === 'announcement') return 'announcement';
  if (s === 'accueil' || s === 'home') return 'home';
  if (s === 'apropos' || s === 'about' || s.includes('propos')) return 'about';
  if (s === 'entreprise' || s === 'company') return 'company';
  return s;
};

const servicesByTitle = new Map((snapshot.services || []).map((s) => [String(s.title || '').trim().toLowerCase(), s]));
const servicesById = new Map((snapshot.services || []).map((s) => [s.id, s]));
const announcementsById = new Map((snapshot.announcements || []).map((a) => [a.id, a]));

function resolveServiceId(rawId, patch) {
  if (rawId && servicesById.has(rawId)) return rawId;

  if (patch?.title) {
    const hit = servicesByTitle.get(String(patch.title).trim().toLowerCase());
    if (hit?.id) return hit.id;
  }

  if (patch?.shortDesc) {
    const needle = String(patch.shortDesc).trim().toLowerCase();
    for (const s of snapshot.services || []) {
      if (String(s.shortDesc || '').trim().toLowerCase() === needle) return s.id;
    }
  }

  const compact = String(rawId || '').toLowerCase().replace(/[^a-f0-9]/g, '');
  if (compact.length >= 20) {
    let bestId = null;
    let bestDistance = Infinity;
    for (const s of snapshot.services || []) {
      const good = String(s.id || '').toLowerCase().replace(/-/g, '');
      if (!good) continue;
      if (compact === good || compact.includes(good) || good.includes(compact)) {
        return s.id;
      }
      const dist = levenshtein(compact, good);
      if (dist < bestDistance) {
        bestDistance = dist;
        bestId = s.id;
      }
    }
    if (bestId && bestDistance <= 4) return bestId;
  }

  return null;
}

function unwrapNestedFields(obj) {
  if (!obj || typeof obj !== 'object' || Array.isArray(obj)) return obj;
  const nested = obj.fields;
  if (nested && typeof nested === 'object' && !Array.isArray(nested)) {
    const { fields: _ignored, ...rest } = obj;
    return { ...rest, ...nested };
  }
  return obj;
}

function levenshtein(a, b) {
  const m = a.length;
  const n = b.length;
  const dp = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0));
  for (let i = 0; i <= m; i++) dp[i][0] = i;
  for (let j = 0; j <= n; j++) dp[0][j] = j;
  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      dp[i][j] = Math.min(
        dp[i - 1][j] + 1,
        dp[i][j - 1] + 1,
        dp[i - 1][j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1),
      );
    }
  }
  return dp[m][n];
}

function coerceShape(u) {
  if (!u || typeof u !== 'object' || Array.isArray(u)) return null;

  let resource = normResource(u.resource);
  let action = u.action;
  let id = isUuid(u.id) ? u.id : undefined;
  let patch = u.patch && typeof u.patch === 'object' && !Array.isArray(u.patch) ? unwrapNestedFields({ ...u.patch }) : null;
  let data = u.data && typeof u.data === 'object' && !Array.isArray(u.data) ? unwrapNestedFields({ ...u.data }) : null;

  if (patch?.id && isUuid(patch.id) && !id) {
    id = patch.id;
    delete patch.id;
  }

  if (!patch && !data && !action) {
    const src = { ...u };
    delete src.resource;
    delete src.action;
    delete src.instructionSummary;
    const maybeId = src.id;
    delete src.id;

    const home = pick(src, HOME_KEYS);
    const about = pick(src, ABOUT_KEYS);
    const company = pick(src, COMPANY_KEYS);
    const service = pick(src, SERVICE_KEYS);
    const ann = pick(src, ANN_KEYS);

    if (maybeId && isUuid(maybeId)) {
      if (servicesById.has(maybeId)) {
        resource = 'service';
        id = maybeId;
        patch = service;
      } else if (announcementsById.has(maybeId)) {
        resource = 'announcement';
        id = maybeId;
        patch = ann;
      } else if (snapshot.home?.id === maybeId) {
        resource = 'home';
        patch = home;
        id = undefined;
      } else if (snapshot.about?.id === maybeId) {
        resource = 'about';
        patch = about;
        id = undefined;
      } else if (snapshot.company?.id === maybeId) {
        resource = 'company';
        patch = company;
        id = undefined;
      }
    }

    if (!resource) {
      const candidates = [
        ['home', home],
        ['about', about],
        ['company', company],
        ['service', service],
        ['announcement', ann],
      ].sort((a, b) => Object.keys(b[1]).length - Object.keys(a[1]).length);

      const [bestResource, bestPatch] = candidates[0] || [];
      if (bestResource && Object.keys(bestPatch).length > 0) {
        resource = bestResource;
        if (bestResource === 'service') {
          if (bestPatch.title) {
            const hit = servicesByTitle.get(String(bestPatch.title).trim().toLowerCase());
            if (hit?.id) id = hit.id;
          }
          if (id) {
            patch = bestPatch;
          } else if (bestPatch.title && bestPatch.shortDesc && bestPatch.detailedDesc && bestPatch.sector) {
            action = 'create';
            data = bestPatch;
            patch = null;
          } else {
            patch = bestPatch;
          }
        } else {
          patch = bestPatch;
        }
      }
    }
  }

  if (!resource || !['home', 'about', 'company', 'service', 'announcement'].includes(resource)) {
    return null;
  }

  const out = { resource };
  if (action === 'create' && data) {
    out.action = 'create';
    out.data = data;
  } else if (action === 'delete' && id) {
    out.id = id;
    out.action = 'delete';
  } else {
    if (patch && Object.keys(patch).length > 0) out.patch = patch;
    if (id && (resource === 'service' || resource === 'announcement')) out.id = id;
  }

  if (['home', 'about', 'company'].includes(resource) && !out.patch) return null;
  if (resource === 'service' && !out.patch && !out.data && out.action !== 'delete') return null;
  if (resource === 'announcement' && !out.patch && !out.data) return null;
  return out;
}

let updates = Array.isArray(parsed.updates) ? parsed.updates : [];
const cleaned = [];

for (const u of updates) {
  const item = coerceShape(u);
  if (!item) continue;

  if (item.resource === 'service' && item.action === 'create' && item.data) {
    item.data = { ...item.data, sector: normSector(item.data.sector) };
    const hit = servicesByTitle.get(String(item.data.title || '').trim().toLowerCase());
    if (hit?.id) {
      item.id = hit.id;
      item.patch = {
        ...(item.data.shortDesc ? { shortDesc: item.data.shortDesc } : {}),
        ...(item.data.detailedDesc ? { detailedDesc: item.data.detailedDesc } : {}),
        ...(item.data.sector ? { sector: item.data.sector } : {}),
        ...(item.data.imageUrl ? { imageUrl: item.data.imageUrl } : {}),
        ...(item.data.title ? { title: item.data.title } : {}),
      };
      delete item.action;
      delete item.data;
    }
  }

  if (item.resource === 'service' && item.patch && !item.action) {
    const resolved = resolveServiceId(item.id, item.patch);
    if (resolved) item.id = resolved;
    if (!isUuid(item.id)) continue;
    if (item.patch.sector) item.patch.sector = normSector(item.patch.sector);
    if (Object.keys(item.patch).length === 0) continue;
  }

  if (item.resource === 'service' && item.action === 'create') {
    if (!item.data?.title || !item.data?.shortDesc || !item.data?.detailedDesc || !item.data?.sector) continue;
    if (!['education', 'enterprise', 'both'].includes(item.data.sector)) continue;
  }

  cleaned.push(item);
}

updates = cleaned;
const instructionSummary = String(parsed.instructionSummary || 'Synchronisation Drive → JMT-S').slice(0, 500);

if (updates.length === 0) {
  return [{ json: { skipApply: true, instructionSummary, updates: [], note: 'Aucune update valide apres nettoyage.' } }];
}

const base = { source: 'n8n-content-sync', instructionSummary, strict: false, updates };
return [{
  json: {
    skipApply: false,
    instructionSummary,
    updates,
    updateCount: updates.length,
    applyDryRun: { ...base, dryRun: true },
    applyReal: { ...base, dryRun: false },
  },
}];

const res = $input.first().json || {};
if (res.status === 'success') {
  return $input.all();
}
if (res.message === 'Invalid payload.' || res.errors) {
  throw new Error('Apply dry-run rejected: ' + JSON.stringify(res.errors || res.message));
}
throw new Error('Apply dry-run failed: ' + JSON.stringify(res));

const config = $('0. Config').first().json;
const agg = $('2h. Aggregate extracted content').first().json;

if (agg?.noUsableContent) {
  return [{
    json: {
      status: 'EXTRACTION_FAILED',
      instructionSummary: agg.extractionNote || 'No usable text extracted from Drive files.',
      updateCount: 0,
      filteredOnServer: 0,
      driveFilesRead: agg.sourceItemCount ?? 0,
      skipped: agg.skipped ?? [],
      extractErrors: agg.extractErrors ?? [],
      skippedFilenames: agg.skippedFilenames ?? [],
      note: agg.extractionNote ?? null,
      baseUrl: config.baseUrl,
    },
  }];
}

const parsed = $('5. Parse AI diff').first().json;

let dryRun = null;
let published = null;
let policy = null;
try { dryRun = $('6. JMT-S Apply dry-run').first().json; } catch {}
try { published = $('8. JMT-S Apply publish').first().json; } catch {}
try { policy = $('7b. Check Policy (publish)').first().json; } catch {}

const updates = parsed.updates ?? parsed.applyDryRun?.updates ?? [];
const updateCount = updates.length;
const allFilteredOnServer = Boolean(dryRun?.filteredCount && !(dryRun?.results?.length));

let status = 'FAILED';
if (parsed.skipApply || allFilteredOnServer) {
  status = 'NO_CHANGES';
} else if (published?.status === 'success') {
  status = 'PUBLISHED';
} else if (dryRun?.status === 'success') {
  status = 'DRY_RUN_OK';
} else {
  status = 'FAILED';
}

return [{
  json: {
    status,
    instructionSummary: parsed.instructionSummary,
    updateCount,
    filteredOnServer: dryRun?.filteredCount ?? 0,
    updatesPreview: updates.slice(0, 5).map((u) => ({
      resource: u.resource,
      action: u.action,
      id: u.id,
      title: u.data?.title ?? u.patch?.title ?? null,
    })),
    driveFilesRead: agg?.fileCount ?? null,
    dryRunStatus: dryRun?.status ?? null,
    dryRunRunId: dryRun?.runId ?? null,
    dryRunMessage: dryRun?.message ?? null,
    publishStatus: published?.status ?? null,
    publishRunId: published?.runId ?? null,
    policyDecision: policy?.decision ?? null,
    policyApprovalId: policy?.approval_id ?? null,
    note: parsed.note ?? dryRun?.message ?? null,
    baseUrl: config.baseUrl,
  },
}];

const subfolderIds = [];
for (const item of $('2b-5 List subfolders L2').all()) {
  if (item.json?.mimeType === 'application/vnd.google-apps.folder' && item.json?.id) {
    subfolderIds.push({ id: item.json.id, name: item.json.name });
  }
}
return [{ json: { subfolderIds } }];

/**
 * Build one-shot Workflow Bridge payload from JMT-S summary + captured steps.
 */
const summary = $('9. Summary').first().json;

function safeJson(nodeName, max = 400) {
  try {
    return JSON.stringify($(nodeName).first().json).slice(0, max);
  } catch {
    return '';
  }
}

function safeSlice(nodeName, path, max = 400) {
  try {
    const j = $(nodeName).first().json;
    const parts = path.split('.');
    let v = j;
    for (const p of parts) v = v?.[p];
    return String(v ?? '').slice(0, max);
  } catch {
    return '';
  }
}

const nodes = [];

nodes.push({
  name: '4. OpenAI diff',
  kind: 'llm',
  purpose: 'Propose CMS updates from Drive documents and site snapshot',
  input_preview: safeSlice('3. Prepare OpenAI', 'messages.1.content'),
  output_preview: safeSlice('4. OpenAI diff', 'choices.0.message.content'),
});

try {
  $('6. JMT-S Apply dry-run').first();
  nodes.push({
    name: '6. JMT-S Apply dry-run',
    kind: 'tool',
    tool_name: 'jmts.content.apply',
    status: summary.dryRunStatus === 'success' ? 'success' : 'skipped',
    output_preview: safeJson('6. JMT-S Apply dry-run'),
  });
} catch {}

try {
  $('8. JMT-S Apply publish').first();
  nodes.push({
    name: '8. JMT-S Apply publish',
    kind: 'tool',
    tool_name: 'jmts.content.publish',
    status: summary.publishStatus === 'success' ? 'success' : 'skipped',
    output_preview: safeJson('8. JMT-S Apply publish'),
  });
} catch {}

const runStatus =
  summary.status === 'FAILED' || summary.status === 'EXTRACTION_FAILED'
    ? 'failed'
    : 'completed';

return [{
  json: {
    obligationTraceId: null,
    aegisBody: {
      one_shot: true,
      business_context: 'JMT-S daily content sync from Google Drive',
      external_system: 'n8n',
      external_workflow_id: String($workflow.id),
      external_execution_id: String($execution.id),
      status: runStatus,
      summary:
        summary.status +
        (summary.updateCount != null ? ': ' + summary.updateCount + ' update(s)' : ''),
      execution: {
        workflow_name: $workflow.name,
        execution_id: String($execution.id),
        nodes,
      },
    },
  },
}];
